mapper.select:
SELECT * FROM ( ( SELECT t.task_id AS source_id, 'AUTO' AS source_type, 'EVAL' AS task_type, t.task_name AS task_name, t.start_time AS start_time, t.end_time AS end_time, t.status AS status, t.create_by AS create_by, t.create_time AS create_time, NULL AS item_count FROM EVAL_TASK t
AND t.status = #{status} AND t.task_name LIKE CONCAT('%', #{keyword}, '%')
) UNION ALL ( SELECT b.batch_id AS source_id, b.source AS source_type, b.task_type AS task_type, COALESCE(b.batch_name, CONCAT('批次', b.batch_id)) AS task_name, b.create_time AS start_time, b.deadline AS end_time, b.status AS status, b.create_by AS create_by, b.create_time AS create_time, COUNT(i.item_id) AS item_count FROM EVAL_ASSIGN_BATCH b LEFT JOIN EVAL_ASSIGN_ITEM i ON b.batch_id = i.batch_id
AND b.status = #{status}
AND (b.batch_name LIKE CONCAT('%', #{keyword}, '%') OR b.create_by LIKE CONCAT('%', #{keyword}, '%'))
GROUP BY b.batch_id ) ) AS unified ORDER BY create_time DESC LIMIT #{limit} OFFSET #{offset}

SELECT SUM(cnt) FROM (
    SELECT COUNT(*) AS cnt FROM EVAL_TASK t

        AND t.status = #{status}
        AND t.task_name LIKE CONCAT('%', #{keyword}, '%')

    UNION ALL
    SELECT COUNT(*) AS cnt FROM EVAL_ASSIGN_BATCH b

        AND b.status = #{status}

            AND (b.batch_name LIKE CONCAT('%', #{keyword}, '%')
                 OR b.create_by LIKE CONCAT('%', #{keyword}, '%'))


) AS t
